SELECT 
FROM pos_topup t



        (t.topup_no LIKE CONCAT('%', #{q.keyword}, '%') OR m.phone = #{q.keyword} OR m.member_code = #{q.keyword})

    AND t.store_id = #{q.storeId}
    AND t.member_id = #{q.memberId}
    AND t.business_date >= #{q.begin}
    AND t.business_date <= #{q.end}

ORDER BY t.id DESC

SELECT 
FROM pos_topup t

WHERE t.id = #{id}

SELECT COUNT(*) AS "topupCount", COALESCE(SUM(amount), 0) AS "topupAmount", COALESCE(SUM(bonus_amount), 0) AS "bonusAmount"
FROM pos_topup
WHERE store_id = #{storeId} AND business_date = #{date}
